attribute vec2 a_pos;
void main() {
  gl_Position = vec4(a_pos, 0.0, 1.0);
}

#define Q_OCT 7
#define F_OCT 8
#define C_OCT 7
#define WITH_DETAIL2 1

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec3 u_skyC0;
uniform vec3 u_skyC1;
uniform vec3 u_skyC2;
uniform vec3 u_skyC3;
uniform vec4 u_skyP;
uniform vec3 u_cloudColor;
uniform vec3 u_cloudShadowColor;
uniform float u_covTop;
uniform float u_covBottom;
uniform float u_density;
uniform float u_brightness;
uniform float u_shadingVariation;
uniform float u_warpAmount;
uniform float u_warpScale;
uniform float u_stretch;
uniform float u_zoom;
uniform vec2 u_pan;
uniform float u_rotation;
uniform float u_evolution;
uniform float u_detail;

/* rotate_scale: per-octave domain rotation+scale from the source shader */
const mat2 ROT = mat2(1.6, -1.2, 1.2, 1.6);
const float CS = 1.56;

vec2 hash2(vec2 p) {
  vec2 q = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return -1.0 + 2.0 * fract(sin(q) * 43758.5453123);
}

/* 2D simplex noise (skew constants K1/K2) */
float noise(vec2 p) {
  const float K1 = 0.366025404;
  const float K2 = 0.211324865;
  vec2 i = floor(p + (p.x + p.y) * K1);
  vec2 a = p - i + (i.x + i.y) * K2;
  vec2 o = (a.x > a.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec2 b = a - o + K2;
  vec2 c = a - 1.0 + 2.0 * K2;
  vec3 h = max(0.5 - vec3(dot(a, a), dot(b, b), dot(c, c)), vec3(0.0));
  vec3 n = h * h * h * h *
    vec3(dot(a, hash2(i)), dot(b, hash2(i + o)), dot(c, hash2(i + 1.0)));
  return dot(n, vec3(70.0));
}

float field(vec2 uv0, int octaves, float startW, float decay, bool ridged, float t) {
  vec2 v = uv0;
  float total = 0.0;
  float w = startW;
  for (int i = 0; i < 8; i++) {
    if (i >= octaves) break;
    float s = noise(v);
    if (ridged) s = abs(s);
    total += w * s;
    v = ROT * v + t;
    w *= decay;
  }
  return total;
}

mat2 rot2(float a) {
  float s = sin(a);
  float c = cos(a);
  return mat2(c, s, -s, c);
}

vec2 applyGlobal(vec2 uvA, float aspect) {
  vec2 centerOff = vec2(0.5 * aspect, 0.5);
  return (uvA - centerOff) * u_zoom + centerOff + u_pan;
}

vec2 applyLayer(vec2 uvA, float aspect, float rotDeg) {
  vec2 centerOff = vec2(0.5 * aspect, 0.5);
  return rot2(radians(rotDeg)) * (uvA - centerOff) + centerOff;
}

vec2 applyStretch(vec2 uvA, float aspect, float stretch) {
  vec2 centerOff = vec2(0.5 * aspect, 0.5);
  vec2 pp = uvA - centerOff;
  pp.x = pp.x / stretch;
  return pp + centerOff;
}

float cloudDensityAt(vec2 uv, float cov, float cd, float cloudT, float wa) {
  float q = field(uv * CS * u_warpScale, Q_OCT, 0.1, 0.4, false, 0.0);
  float r = field(uv * CS - (q * wa - cloudT), F_OCT, 0.8, 0.7 * cd, true, cloudT);
  float f = field(uv * CS - (q * wa - cloudT), F_OCT, 0.7, 0.6 * cd, false, cloudT);
  f = f * (r + f);
  return cov + u_density * f * r;
}

vec3 skyGradient(float t) {
  if (t <= u_skyP.x) { return u_skyC0; }
  if (t <= u_skyP.y) {
    return mix(u_skyC0, u_skyC1, (t - u_skyP.x) / max(u_skyP.y - u_skyP.x, 0.0001));
  }
  if (t <= u_skyP.z) {
    return mix(u_skyC1, u_skyC2, (t - u_skyP.y) / max(u_skyP.z - u_skyP.y, 0.0001));
  }
  if (t <= u_skyP.w) {
    return mix(u_skyC2, u_skyC3, (t - u_skyP.z) / max(u_skyP.w - u_skyP.z, 0.0001));
  }
  return u_skyC3;
}

void main() {
  /* Source samples with uv.y = 0 at the TOP; gl_FragCoord.y is bottom-up. */
  vec2 p = vec2(
    gl_FragCoord.x / u_resolution.x,
    1.0 - gl_FragCoord.y / u_resolution.y
  );
  float aspect = u_resolution.x / u_resolution.y;

  vec2 baseA = p * vec2(aspect, 1.0);
  vec2 g = applyGlobal(baseA, aspect);
  vec2 gs = applyStretch(g, aspect, u_stretch);
  vec2 cloudUV = applyLayer(gs, aspect, u_rotation);

  float cd = clamp(u_detail, 0.4, 1.4);

  float cloudT = u_evolution;
  float wa = u_warpAmount;

  float q = field(cloudUV * CS * u_warpScale, Q_OCT, 0.1, 0.4, false, 0.0);
  float r = field(cloudUV * CS - (q * wa - cloudT), F_OCT, 0.8, 0.7 * cd, true, cloudT);
  float f = field(cloudUV * CS - (q * wa - cloudT), F_OCT, 0.7, 0.6 * cd, false, cloudT);
  f = f * (r + f);

  float cloudT2 = u_evolution * 2.0;
  float c = field(cloudUV * CS * 2.0 - (q * wa - cloudT2), C_OCT, 0.4, 0.6 * cd, false, cloudT2);
#if WITH_DETAIL2
  float cloudT3 = u_evolution * 3.0;
  float c1 = field(cloudUV * CS * 3.0 - (q * wa - cloudT3), C_OCT, 0.4, 0.6 * cd, true, cloudT3);
  c = c + c1;
#endif

  /* Vertical coverage mix — the design's skies are clear up top and
     hazy toward the horizon. */
  float cov = mix(u_covTop, u_covBottom, p.y);
  float fd = cov + u_density * f * r;

  /* Sun direction is fixed in the source shader (140deg). */
  const vec2 sunDir = vec2(-0.76604444, 0.64278761);
  float dLit = cloudDensityAt(cloudUV + sunDir * 0.15, cov, cd, cloudT, wa);
  float diffuse = clamp((fd - dLit) / (u_density * 0.15 + 0.001), 0.0, 1.0);

  vec3 sky = skyGradient(p.y);
  float shading = clamp(u_brightness + u_shadingVariation * c + 0.15 * diffuse, 0.0, 1.0);
  vec3 cloud = mix(u_cloudShadowColor, u_cloudColor, shading);
